import api from "./api";
import { FEATURES, STORAGE_KEYS } from "../constants/AppConstants";

// ---- session persistence -------------------------------------------------

function saveSession(session) {
  localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify(session));
  return session;
}

function getSession() {
  const raw = localStorage.getItem(STORAGE_KEYS.SESSION);
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function clearSession() {
  localStorage.removeItem(STORAGE_KEYS.SESSION);
}

// ---- mock backend (used only if the real API call fails/unreachable) ----
// Kept intentionally obvious/isolated so swapping to a live Spring Boot
// backend is just: set FEATURES.ENABLE_MOCK_FALLBACK = false.

function mockLogin(username, password) {
  if (!username || !password) {
    return Promise.reject(new Error("Username and password are required."));
  }
  const user = {
    id: "u-" + username.toLowerCase(),
    username,
    fullName: username
      .replace(/[._]/g, " ")
      .replace(/\b\w/g, (c) => c.toUpperCase()),
    studentId: "246" + String(Math.floor(1000000 + Math.random() * 8999999)),
    role: "STUDENT",
    isGuest: false,
  };
  return Promise.resolve({
    token: "mock-jwt-" + btoa(username + ":" + Date.now()),
    user,
  });
}

function mockGuest() {
  const user = {
    id: "guest-" + Date.now(),
    username: "guest",
    fullName: "Guest",
    studentId: null,
    role: "GUEST",
    isGuest: true,
  };
  return Promise.resolve({
    token: "mock-guest-" + Date.now(),
    user,
  });
}

// ---- public API ------------------------------------------------------------

const AuthService = {
  async login(username, password) {
    try {
      const { data } = await api.post("/auth/login", { username, password });
      return saveSession({ token: data.token, user: data.user });
    } catch (err) {
      const backendResponded = !!err.response;
      if (backendResponded) {
        // Real backend rejected the credentials — surface its message.
        const message =
          err.response.data?.message || "Invalid username or password.";
        throw new Error(message);
      }
      if (!FEATURES.ENABLE_MOCK_FALLBACK) throw err;
      // Backend unreachable (e.g. not running yet) — demo with the mock.
      const data = await mockLogin(username, password);
      return saveSession({ token: data.token, user: data.user, mock: true });
    }
  },

  async loginAsGuest() {
    try {
      const { data } = await api.post("/auth/guest");
      return saveSession({ token: data.token, user: data.user });
    } catch (err) {
      if (!FEATURES.ENABLE_MOCK_FALLBACK) throw err;
      const data = await mockGuest();
      return saveSession({ token: data.token, user: data.user, mock: true });
    }
  },

  async requestPasswordReset(username) {
    try {
      await api.post("/auth/forgot-password", { username });
      return { sent: true };
    } catch (err) {
      if (!FEATURES.ENABLE_MOCK_FALLBACK) throw err;
      return { sent: true, mock: true };
    }
  },

  logout() {
    clearSession();
  },

  getCurrentUser() {
    return getSession()?.user || null;
  },

  isAuthenticated() {
    return !!getSession()?.token;
  },

  isGuest() {
    return !!getSession()?.user?.isGuest;
  },
};

export default AuthService;
